const item = $input.first().json;
const rawText = item.text || item.transcript || '';

// 1. Chuẩn hóa khoảng trắng, loại bỏ ký tự điều khiển lạ
const cleanedText = rawText
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// 2. Kiểm tra nếu file audio không có giọng nói hoặc trả về rỗng
if (!cleanedText) {
  throw new Error("Không phát hiện nội dung văn bản từ file ghi âm cuộc họp.");
}

// 3. Tính toán siêu dữ liệu cơ bản
const wordCount = cleanedText.split(' ').filter(w => w.length > 0).length;

return [
  {
    json: {
      original_text: rawText,
      transcript: cleanedText,
      word_count: wordCount,
      processed_at: new Date().toISOString()
    }
  }
];

const inputData = $input.first().json;

// 1. Lấy nội dung chuỗi JSON từ kết quả trả về của LLM
let rawContent = '';
if (inputData.choices && inputData.choices[0] && inputData.choices[0].message) {
  rawContent = inputData.choices[0].message.content;
} else if (typeof inputData === 'string') {
  rawContent = inputData;
} else {
  rawContent = JSON.stringify(inputData);
}

// 2. Parse chuỗi JSON với cơ chế fallback phòng trường hợp dính markdown format
let parsedData = {};
try {
  // Loại bỏ các thẻ code block ```json nếu có
  const cleanJson = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
  parsedData = JSON.parse(cleanJson);
} catch (error) {
  throw new Error("Không thể parse dữ liệu JSON từ LLM: " + error.message + "\nNội dung thô: " + rawContent);
}

const summary = parsedData.meeting_summary || 'Không có tóm tắt cuộc họp.';
const actionItems = Array.isArray(parsedData.action_items) ? parsedData.action_items : [];

// 3. Nếu không có task nào, trả về 1 item mang cờ báo has_tasks = false
if (actionItems.length === 0) {
  return [
    {
      json: {
        has_tasks: false,
        meeting_summary: summary,
        total_tasks: 0
      }
    }
  ];
}

// 4. Chuẩn hóa từng task thành 1 item riêng biệt trong n8n
return actionItems.map((item, index) => {
  return {
    json: {
      has_tasks: true,
      task_index: index + 1,
      total_tasks: actionItems.length,
      meeting_summary: summary,
      summary: (item.summary || `Task ${index + 1}`).trim(),
      description: (item.description || 'Không có mô tả chi tiết.').trim(),
      priority: ['High', 'Medium', 'Low'].includes(item.priority) ? item.priority : 'Medium',
      issue_type: item.issue_type || 'Task'
    }
  };
});

