const items = $input.all();

// Lấy thông tin tóm tắt cuộc họp từ Node 7
const meetingSummary = $('Code (Parse & Normalize Tasks)').first().json.meeting_summary || 'Không có tóm tắt.';

// Gom danh sách các task đã tạo trên Jira
const createdTasks = items.map((item, index) => {
  const json = item.json;
  // Jira trả về key (ví dụ: ESFLDHJA-2) và self API URL
  const issueKey = json.key || `Task-${index + 1}`;

  // Trích xuất domain Jira để dựng URL xem trực tiếp trên browser
  let browseUrl = '';
  if (json.self) {
    const domainMatch = json.self.match(/https:\/\/[^\/]+/);
    if (domainMatch) {
      browseUrl = `${domainMatch[0]}/browse/${issueKey}`;
    }
  }

  return {
    key: issueKey,
    id: json.id,
    url: browseUrl
  };
});

// Định dạng văn bản báo cáo cho Slack / Email / Webhook
let formattedReport = `📋 *KẾT QUẢ XỬ LÝ BIÊN BẢN CUỘC HỌP*\n\n`;
formattedReport += `📝 *Tóm tắt cuộc họp:*\n${meetingSummary}\n\n`;
formattedReport += `📌 *Danh sách Jira Tasks đã tạo (${createdTasks.length}):*\n`;

createdTasks.forEach((task, idx) => {
  if (task.url) {
    formattedReport += `${idx + 1}. <${task.url}|${task.key}>\n`;
  } else {
    formattedReport += `${idx + 1}. ${task.key}\n`;
  }
});

return [
  {
    json: {
      status: "success",
      total_created: createdTasks.length,
      meeting_summary: meetingSummary,
      tasks: createdTasks,
      report_message: formattedReport,
      created_at: new Date().toISOString()
    }
  }
];

